/**
 * Material Icon Theme's matching (YAZ-3440 D4), ported for the sidebar tree: which of its icons a file or a folder
 * row shows. O(1) per row: the release's tables (`materialIconData.ts`, generated by
 * `tools/materialIcons.mjs`) become Maps once, when they load, and a row asks one Map per dot in its name.
 *
 * Files, as VS Code reads Material's manifest: an exact file name wins (`README.md`, `Makefile`, `.gitignore`,
 * `package.json`), then the longest extension (`test.ts` before `ts`; `.env` has the extension `env`), then the
 * default file. Names and extensions match in any case. Material's language-id table is not ported: the app has
 * no language ids, and the manifest's extension table covers the kinds it lists.
 * Folders: by name in any case, also with Material's prefixes (`.github`, `_lib`, `-docs`, `__tests__`), else the
 * default folder; an open folder shows its `-open` icon. A vault row shows none (Tree.tsx).
 *
 * The icons are files under `/material-icons/` (client/public), so a row loads only the icon it shows; in the
 * light theme an icon with a `_light` twin shows that one (Material's `light` table does the same).
 *
 * The tables load LAZILY (YAZ-3470): `materialIconData.ts` (84 KB) is its own chunk, out of the startup bundle.
 * `main.tsx` starts `loadMaterialIcons()` beside the app state's load, so the tables are there before a tree has
 * rows in practice. Until they are, a file matches the default file and a folder the default folder, and no id is
 * Material's (a pick waits). `useMaterialIcons()` re-renders a component once they land, and `buildRowIcons` gives
 * the tree a new `RowIcons` then, so each level renders once more (`iconsChangedBelow`).
 */
import { useSyncExternalStore } from 'react'

interface Tables {
  fileName: Map<string, string>
  fileExtension: Map<string, string>
  folderName: Map<string, string>
  ids: Set<string>
  clones: Set<string>
}

const tableOf = (grouped: Record<string, string>): Map<string, string> => {
  const map = new Map<string, string>()
  for (const [icon, keys] of Object.entries(grouped)) for (const key of keys.split(' ')) map.set(key, icon)
  return map
}

let tables: Tables | null = null
let loading: Promise<void> | null = null
const listeners = new Set<() => void>()

/** Load the tables once (the first call imports the chunk; later calls get the same promise). */
export function loadMaterialIcons(): Promise<void> {
  loading ??= import('./materialIconData').then((data) => {
    tables = {
      fileName: tableOf(data.FILE_NAMES),
      fileExtension: tableOf(data.FILE_EXTENSIONS),
      folderName: tableOf(data.FOLDER_NAMES),
      ids: new Set(data.MATERIAL_IDS.split(' ')),
      clones: new Set(data.MATERIAL_CLONES.split(' ')),
    }
    for (const listener of listeners) listener()
  }, () => {
    // A chunk that fails to load leaves the defaults; a later call tries again.
    loading = null
  })
  return loading
}

/** True once the tables are loaded. */
export const materialIconsLoaded = (): boolean => tables !== null

const subscribe = (listener: () => void): (() => void) => {
  listeners.add(listener)
  return () => listeners.delete(listener)
}

/** Whether the tables are loaded, live: it starts the load, and the component renders again once they land. */
export function useMaterialIcons(): boolean {
  if (tables === null) void loadMaterialIcons()
  return useSyncExternalStore(subscribe, materialIconsLoaded)
}

const DEFAULT_FILE_ICON = 'file'
/** Material's default folder: every folder's icon with "Plain" (YAZ-3554), and any folder before the tables load. */
export const DEFAULT_FOLDER_ICON = 'folder'

/** True for an id Material ships: a pick or a rule naming any other reads as no pick (YAZ-3440 D8). */
export const isMaterialIcon = (id: string): boolean => tables?.ids.has(id) === true

/** The icon of a file named `name` (its base name, not a path). */
export function materialFileIcon(name: string): string {
  if (tables === null) return DEFAULT_FILE_ICON
  const lower = name.toLowerCase()
  const exact = tables.fileName.get(lower)
  if (exact !== undefined) return exact
  // Each suffix after a dot, longest first: `a.test.ts` asks `test.ts`, then `ts`.
  for (let dot = lower.indexOf('.'); dot !== -1; dot = lower.indexOf('.', dot + 1)) {
    const icon = tables.fileExtension.get(lower.slice(dot + 1))
    if (icon !== undefined) return icon
  }
  return DEFAULT_FILE_ICON
}

/** Material's folder-name variants (`extendFolderNames`): `name`, `.name`, `_name`, `-name`, `__name__`. */
const PLAIN = /^(?:__(.+)__|[._-](.+))$/

/** The icon of a CLOSED folder named `name`; `openIcon` gives its open one. */
export function materialFolderIcon(name: string): string {
  if (tables === null) return DEFAULT_FOLDER_ICON
  const lower = name.toLowerCase()
  const exact = tables.folderName.get(lower)
  if (exact !== undefined) return exact
  const m = PLAIN.exec(lower)
  const base = m?.[1] ?? m?.[2]
  return (base === undefined ? undefined : tables.folderName.get(base)) ?? DEFAULT_FOLDER_ICON
}

/** A folder icon's open twin (`folder-src` → `folder-src-open`), or the icon itself when Material has none. */
export const openIcon = (id: string): string => (tables?.ids.has(`${id}-open`) === true ? `${id}-open` : id)

/** Where an icon's file is served: an absolute path, so it resolves the same from inline style and from app.css. */
export const iconUrl = (id: string): string => `/material-icons/${id}${tables?.clones.has(id) === true ? '.clone' : ''}.svg`

/** The `_light` twin of an icon, for the light theme, or null when it has none. */
const lightIcon = (id: string): string | null => (tables?.ids.has(`${id}_light`) === true ? `${id}_light` : null)

/**
 * The inline custom properties that draw `id` on a row (app.css reads them on `.tree__label::before`): its URL,
 * and its light twin's when it has one. A new object per call: Tree builds it during render, beside `paddingLeft`.
 */
export function iconVars(id: string): Record<string, string> {
  const light = lightIcon(id)
  return light === null ? { '--icon': `url(${iconUrl(id)})` } : { '--icon': `url(${iconUrl(id)})`, '--icon-light': `url(${iconUrl(light)})` }
}

/** The ids the icon picker lists: every icon but the open and the light twins, which follow their icon. None before the tables load. */
export function pickableIcons(): string[] {
  const ids = tables?.ids ?? new Set<string>()
  return [...ids].filter((id) => !(id.endsWith('-open') && ids.has(id.slice(0, -5))) && !(id.endsWith('_light') && ids.has(id.slice(0, -6))))
}
